-- CreateEnum
CREATE TYPE "SalesActivityType" AS ENUM ('SETTING', 'CLOSING', 'UPSELL', 'OUTBOUND_CALL', 'OUTBOUND_DM', 'COLD_EMAIL', 'LOOM_SALES_LETTER');

-- CreateTable
CREATE TABLE "SalesActivityLog" (
    "id" TEXT NOT NULL,
    "organizationId" TEXT NOT NULL,
    "activityType" "SalesActivityType" NOT NULL,
    "personName" TEXT NOT NULL,
    "activityDate" TIMESTAMP(3) NOT NULL,
    "metrics" JSONB NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "SalesActivityLog_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "SalesActivityLog_organizationId_activityType_activityDate_idx" ON "SalesActivityLog"("organizationId", "activityType", "activityDate");

-- AddForeignKey
ALTER TABLE "SalesActivityLog" ADD CONSTRAINT "SalesActivityLog_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;


